    const updatedAt = row.updated_at as string;
    const effectiveHalfLife = DECAY_HALF_LIFE_DAYS * importanceMultiplier(row);
    score *= computeDecayFactor(updatedAt, effectiveHalfLife);
  }

  return { memory: rowToMemory(row), score };
}

